import * as THREE from 'three';

const $=s=>document.querySelector(s), canvas=$('#scene');
const scene=new THREE.Scene(); scene.background=new THREE.Color('#a5b6ae'); scene.fog=new THREE.FogExp2('#a5b6ae',.0088);
const camera=new THREE.PerspectiveCamera(54,innerWidth/innerHeight,.1,450);
const renderer=new THREE.WebGLRenderer({canvas,antialias:false,powerPreference:'low-power'}); renderer.setPixelRatio(Math.min(devicePixelRatio,1.35)); renderer.setSize(innerWidth,innerHeight); renderer.shadowMap.enabled=true; renderer.shadowMap.type=THREE.BasicShadowMap; renderer.outputColorSpace=THREE.SRGBColorSpace; renderer.toneMapping=THREE.ACESFilmicToneMapping; renderer.toneMappingExposure=1.2;
scene.add(new THREE.HemisphereLight(0xc9e1d5,0x51483b,2.1));
const sun=new THREE.DirectionalLight(0xffe6ba,3.3); sun.position.set(-35,58,25); sun.castShadow=true; sun.shadow.mapSize.set(1024,1024); sun.shadow.camera.left=-42;sun.shadow.camera.right=42;sun.shadow.camera.top=42;sun.shadow.camera.bottom=-42; scene.add(sun);
const fill=new THREE.DirectionalLight(0x9abdb8,.7);fill.position.set(30,18,-20);scene.add(fill);
const mat=(color,rough=.9)=>new THREE.MeshStandardMaterial({color,roughness:rough,flatShading:true});
const mats={bark:mat('#644b37'),leaf:mat('#526c4b'),leaf2:mat('#738458'),darkLeaf:mat('#283b37'),darkLeaf2:mat('#405047'),rock:mat('#77776b'),rock2:mat('#a29a84'),grass:mat('#677b58'),soil:mat('#85765a'),hill:mat('#94846b'),gold:mat('#d7ba70'),marble:mat('#ded6bf'),shade:mat('#263b4a'),shadeGlow:mat('#78d9cc'),white:mat('#eee5ce'),skin:mat('#c78d64'),tunic:mat('#a46042'),leather:mat('#49392d')};
const geo={box:new THREE.BoxGeometry(1,1,1),sphere:new THREE.IcosahedronGeometry(1,1),tree:new THREE.CylinderGeometry(.13,.25,2.3,5),cone:new THREE.ConeGeometry(1,1,6),cyl:new THREE.CylinderGeometry(.5,.5,1,8)};
function mesh(g,m,x=0,y=0,z=0,sx=1,sy=1,sz=1){const o=new THREE.Mesh(g,m);o.position.set(x,y,z);o.scale.set(sx,sy,sz);o.castShadow=true;o.receiveShadow=true;scene.add(o);return o}
function rndFactory(seed){return()=>{seed=(seed*1664525+1013904223)>>>0;return seed/4294967296}}const rand=rndFactory(9327);
// Four broad, traversable realms: progressively stranger and more dangerous to the north.
const zones=[{name:'THE OLIVE WOODS',z0:42,z1:-34,ground:'#70815d',fog:'#a8b8a5',density:.008,trees:'woods'},{name:'THE DARK WOODS',z0:-34,z1:-98,ground:'#485a4a',fog:'#788b82',density:.012,trees:'dark'},{name:'THE WIND-SCARRED HILLS',z0:-98,z1:-162,ground:'#857b68',fog:'#aaa18c',density:.006,trees:'hills'},{name:'ELYSIUM',z0:-162,z1:-236,ground:'#b8a77a',fog:'#e4ce93',density:.005,trees:'elysium'}];
function terrainY(x,z){let y=Math.sin(x*.115+z*.06)*.22+Math.cos(z*.13-x*.055)*.2;if(z<-95&&z>-162)y+=Math.sin(x*.13+z*.1)*1.5+Math.cos(x*.17-z*.08)*.85;if(z<-162)y+=Math.sin(x*.08+z*.04)*.35;return y}
for(const zone of zones){const geoG=new THREE.PlaneGeometry(130,zone.z0-zone.z1,60,Math.max(28,Math.round((zone.z0-zone.z1)*.52)));geoG.rotateX(-Math.PI/2);const p=geoG.attributes.position;for(let i=0;i<p.count;i++){const x=p.getX(i),z=p.getZ(i)+(zone.z0+zone.z1)/2;p.setY(i,terrainY(x,z));}geoG.computeVertexNormals();const gr=new THREE.Mesh(geoG,mat(zone.ground));gr.receiveShadow=true;scene.add(gr);zone.groundMesh=gr;}
// World detail: trees, stones, little landmarks and winding trails.
const treeGroups=[];
function makeTree(x,z,kind,scale=1){const y=terrainY(x,z),g=new THREE.Group();g.position.set(x,y,z);g.scale.setScalar(scale);scene.add(g);let trunk=new THREE.Mesh(geo.tree,mat(kind==='dark'?'#42392e':kind==='elysium'?'#a89769':'#68513a'));trunk.position.y=1.15;trunk.castShadow=true;g.add(trunk);
 if(kind==='woods'||kind==='dark'){let lm=kind==='dark'?mats.darkLeaf:mats.leaf, lm2=kind==='dark'?mats.darkLeaf2:mats.leaf2;for(let i=0;i<3;i++){let crown=new THREE.Mesh(geo.cone,i===1?lm2:lm);crown.position.set((rand()-.5)*.24,2.1+i*.7,0);crown.scale.set(1.05-i*.13,1.8-i*.15,1);crown.castShadow=true;g.add(crown)}}else if(kind==='hills'){const cl=new THREE.Mesh(geo.sphere,mat('#b5a68c'));cl.position.y=2.2;cl.scale.set(.65,.38,.55);g.add(cl);for(let n=0;n<3;n++){const tuft=new THREE.Mesh(geo.cone,mat('#77785c'));tuft.position.set((rand()-.5)*.9,1.9,(rand()-.5)*.7);tuft.scale.set(.42,.85,.42);g.add(tuft)}}else{const crown=new THREE.Mesh(geo.sphere,mat('#d0c58e'));crown.position.y=2.15;crown.scale.set(.7,.5,.7);g.add(crown);for(let n=0;n<4;n++){const blossom=new THREE.Mesh(geo.sphere,mat(['#f2e7c2','#ead5a2','#f5e9d2'][n%3]));blossom.position.set((rand()-.5)*1.2,2.05+rand()*.45,(rand()-.5)*1.1);blossom.scale.setScalar(.23);g.add(blossom)}}treeGroups.push(g);return g}
function makeRock(x,z,s=1,color=mats.rock){let r=mesh(geo.sphere,color,x,terrainY(x,z)+s*.28,z,s*.62,s*.45,s*.53);r.rotation.set(rand()*.7,rand()*3,rand()*.5);return r}
for(const zone of zones){let tries=zone.trees==='dark'?115:zone.trees==='woods'?105:zone.trees==='hills'?72:80;for(let i=0;i<tries;i++){let x=(rand()-.5)*112,z=zone.z1+rand()*(zone.z0-zone.z1);if(Math.abs(x)<4&&z> -18)continue;makeTree(x,z,zone.trees,.8+rand()*.65)}for(let i=0;i<32;i++){let x=(rand()-.5)*106,z=zone.z1+rand()*(zone.z0-zone.z1);makeRock(x,z,.45+rand()*1.25,zone.trees==='elysium'?mats.marble:mats.rock)}}
// Hillside peaks frame the journey in the high country.
for(let i=0;i<18;i++){let x=(rand()-.5)*106,z=-101-rand()*54;let h=5+rand()*11,o=mesh(geo.cone,mat('#8e806b'),x,terrainY(x,z)+h*.4,z,h*.75,h,h*.8);o.rotation.z=(rand()-.5)*.18}
// A pale processional path through all four regions.
for(let z=32;z>-221;z-=2.2){let x=Math.sin(z*.038)*4.1;const y=terrainY(x,z)+.025;const stone=mesh(geo.box,mat(z<-162?'#d8c99e':z<-98?'#a5997d':'#9e9277'),x+(rand()-.5)*1.2,y,z,1.5+rand()*.8,.055,1.75+rand()*.4);stone.rotation.y=(rand()-.5)*.3;stone.castShadow=false}
// small olive grove details and flowers
for(let i=0;i<120;i++){let z=35-rand()*250,x=(rand()-.5)*95;if(rand()>.48){const f=mesh(geo.cone,mat(z<-162?'#e4d7ad':z<-98?'#a19a77':'#77875f'),x,terrainY(x,z)+.22,z,.13,.4,.13);f.castShadow=false}}
// distant boundary mountain silhouettes
for(let side of [-1,1])for(let i=0;i<14;i++){let z=-87-i*6,x=side*(65+rand()*22),h=12+rand()*22;let m=mesh(geo.cone,mat('#596458'),x,h*.34,z,h*.65,h,h*.75);m.castShadow=false}
// Player character, handcrafted from low-poly primitives.
const player=new THREE.Group();scene.add(player);const avatar=new THREE.Group();player.add(avatar);
function part(parent,g,m,x,y,z,sx,sy,sz){const o=new THREE.Mesh(g,m);o.position.set(x,y,z);o.scale.set(sx,sy,sz);o.castShadow=true;o.receiveShadow=true;parent.add(o);return o}
part(avatar,geo.cyl,mats.tunic,0,1.03,0,.4,.83,.29);part(avatar,geo.sphere,mats.skin,0,1.72,0,.235,.25,.23);part(avatar,geo.cyl,mats.leather,0,1.39,0,.405,.12,.3);
const hair=part(avatar,geo.sphere,mat('#4b382d'),0,1.83,-.025,.25,.14,.245);
const armL=part(avatar,geo.cyl,mats.skin,-.31,1.08,0,.105,.52,.11),armR=part(avatar,geo.cyl,mats.skin,.31,1.08,0,.105,.52,.11);armL.rotation.z=-.16;armR.rotation.z=.16;
const legL=part(avatar,geo.cyl,mat('#625342'),-.13,.42,0,.13,.58,.14),legR=part(avatar,geo.cyl,mat('#625342'),.13,.42,0,.13,.58,.14);
part(avatar,geo.box,mat('#b29a6d'),0,1.13,.17,.24,.055,.06);
const spear=part(avatar,geo.cyl,mat('#8c6841'),.39,1.13,-.05,.045,.95,.045);spear.rotation.z=-.65;const spearHead=part(avatar,geo.cone,mats.marble,.68,1.55,-.05,.09,.24,.09);spearHead.rotation.z=-.68;
player.position.set(0,terrainY(0,4),4);let facing=0,moveX=0,moveZ=0,health=100,stamina=100,wood=0,stone=0,shards=0,gameOn=false,won=false,attackCooldown=0,dodgeTime=0,invuln=0,day=1,toastTimer=0,biomeTimer=0,lastBiome='';let kills=0;
// Gatherables and altar interaction markers.
const resources=[];
function resource(type,x,z){let y=terrainY(x,z),g=new THREE.Group();g.position.set(x,y,z);scene.add(g);let o;if(type==='wood'){o=new THREE.Mesh(geo.box,mat('#a78054'));o.scale.set(.22,.3,.2);o.rotation.z=.18;o.position.y=.2;g.add(o);let twig=new THREE.Mesh(geo.box,mat('#c09a65'));twig.scale.set(.12,.22,.11);twig.position.set(.13,.28,0);twig.rotation.z=-.6;g.add(twig)}else if(type==='stone'){o=new THREE.Mesh(geo.sphere,mats.rock2);o.scale.set(.35,.25,.32);o.position.y=.2;g.add(o)}else{const ring=new THREE.Mesh(new THREE.TorusGeometry(.24,.065,5,8),mats.shadeGlow);ring.rotation.x=Math.PI/2;ring.position.y=.7;g.add(ring);const crystal=new THREE.Mesh(geo.cone,mat('#72d6cc',.4));crystal.position.y=.72;crystal.scale.set(.19,.62,.19);crystal.rotation.z=.12;g.add(crystal);const light=new THREE.PointLight('#68dfd0',1.3,5);light.position.y=1;g.add(light)}g.traverse(o=>{if(o.isMesh){o.castShadow=true}});resources.push({type,x,y,z,group:g,active:true});}
for(let i=0;i<12;i++){let z=24-rand()*64,x=(rand()-.5)*30;resource('wood',x,z)}for(let i=0;i<12;i++){let z=-25-rand()*92,x=(rand()-.5)*36;resource('stone',x,z)}
// Enemies: shades in the dark woods, hills and Elysium.
const enemies=[];
function makeShade(x,z,boss=false){const g=new THREE.Group();scene.add(g);g.position.set(x,terrainY(x,z),z);const robe=part(g,geo.cone,mat(boss?'#425d63':'#293d49'),0,.78,0,.42,boss?1.65:1.35,.42);const hood=part(g,geo.sphere,mat('#182a32'),0,boss?1.62:1.28,0,.31,.34,.3);const eye1=part(g,geo.sphere,mat('#70e4d2',.4),-.105,boss?1.64:1.3,.25,.047,.05,.035),eye2=part(g,geo.sphere,mat('#70e4d2',.4),.105,boss?1.64:1.3,.25,.047,.05,.035);const aura=new THREE.PointLight('#64c9bd',boss?1.2:.55,4);aura.position.y=1.2;g.add(aura);enemies.push({g,x,z,hp:boss?5:2,boss,attack:0,phase:rand()*8,alive:true});return g}
for(let i=0;i<10;i++){let z=-44-rand()*96,x=(rand()-.5)*28;makeShade(x,z)}
for(let i=0;i<4;i++){let z=-164-rand()*50,x=(rand()-.5)*25;makeShade(x,z)}
makeShade(2,-203,true);
// Greek shrine at Elysium, goal of the journey.
const altar=new THREE.Group();altar.position.set(0,terrainY(0,-213),-213);scene.add(altar);
for(let i=0;i<3;i++){let base=part(altar,geo.cyl,mat('#d1c5a4'),0,.14+i*.16,0,1.45-i*.17,.25,.95);base.rotation.y=Math.PI/4}
const columnMat=mat('#d8cfb4');for(let s of [-1,1])for(let x of [-.85,.85]){part(altar,geo.cyl,columnMat,x,1.05,s*.45,.17,1.25,.17);for(let j=0;j<4;j++){let groove=part(altar,geo.cyl,mat('#c0b59b'),x,1.05,s*.45,.178,.025,.178);groove.position.y=.59+j*.3}}
part(altar,geo.box,columnMat,0,1.74,0,2.2,.22,1.25);const flame=new THREE.Mesh(geo.sphere,mat('#7ce2cf',.35));flame.position.set(0,2.1,0);flame.scale.set(.32,.54,.32);altar.add(flame);const altarLight=new THREE.PointLight('#75dfd0',0,20);altarLight.position.set(0,2,0);altar.add(altarLight);
// UI and controls.
const keys={};let promptTarget=null;function showToast(t){const el=$('#toast');el.textContent=t;el.classList.add('show');toastTimer=2.25}
function currentBiome(z=player.position.z){return zones.find(q=>z<=q.z0&&z>q.z1)||zones[zones.length-1]}
function updateQuest(){let title,copy,progress,count,pct;if(wood+stone<3){title='A SPARK IN THE WILD';copy='The old ways are fading. Gather what the land gives freely.';progress='Gather branches and stone';count=`${Math.min(wood+stone,3)} / 3`;pct=Math.min((wood+stone)/3,1)}else if(shards<3){title='WHERE SHADOWS GATHER';copy='The ember is split. Follow the old road north and reclaim its light.';progress='Find ember fragments';count=`${shards} / 3`;pct=shards/3}else{title='THE LAST FLAME';copy='The altar waits in Elysium. Bring the ember home.';progress='Awaken the altar in Elysium';count=player.position.z<-207?'READY':'—';pct=player.position.z<-207?1:.65}$('#quest-title').textContent=title;$('#quest-copy').textContent=copy;$('#quest-progress').textContent=progress;$('#quest-count').textContent=count;$('#quest-bar').style.width=`${pct*100}%`}
function updateUI(){ $('#health-fill').style.width=`${health}%`;$('#health-value').textContent=Math.ceil(health);$('#stamina-fill').style.width=`${stamina}%`;$('#stamina-value').textContent=Math.ceil(stamina);$('#wood-count').textContent=wood;$('#stone-count').textContent=stone;$('#shard-count').textContent=shards;$('#day-count').textContent=['I','II','III','IV'][Math.min(day-1,3)];updateQuest() }
function setBiome(){let b=currentBiome();if(lastBiome!==b.name){lastBiome=b.name;$('#biome-name').textContent=b.name;const c=new THREE.Color(b.fog);scene.fog.color.copy(c);scene.background.copy(c);biomeTimer=3.1;showToast(b.name);}}
function nearestTarget(){let best=null,d=3.2;for(const r of resources){if(!r.active)continue;let dd=Math.hypot(player.position.x-r.x,player.position.z-r.z);if(dd<d){best={type:'resource',obj:r,d:dd};d=dd}}for(const e of enemies){if(!e.alive)continue;let dd=Math.hypot(player.position.x-e.x,player.position.z-e.z);if(dd<d){best={type:'enemy',obj:e,d:dd};d=dd}}let ad=player.position.distanceTo(altar.position);if(ad<4.2&&ad<d)best={type:'altar',obj:altar,d:ad};return best}
function interact(){const t=nearestTarget();if(!t)return;if(t.type==='resource'){const r=t.obj;r.active=false;r.group.visible=false;if(r.type==='wood'){wood++;showToast('GATHERED · OLIVE WOOD')}else if(r.type==='stone'){stone++;showToast('GATHERED · STONE')}else{shards++;showToast('EMBER FRAGMENT RESTORED');altarLight.intensity=.7+shards*.2}updateUI()}else if(t.type==='altar'){if(shards>=3){won=true;$('#end-title').textContent='THE FLAME RETURNS';$('#end-copy').textContent='The altar drinks the ember. A new dawn rises over the four realms.';$('#end-screen').classList.add('visible')}else showToast(`THE ALTAR IS COLD · ${3-shards} EMBER${3-shards===1?'':'S'} LOST`)}}
function attack(){if(!gameOn||attackCooldown>0||stamina<11)return;attackCooldown=.58;stamina-=11;avatar.rotation.y=-.75;setTimeout(()=>{if(avatar)avatar.rotation.y=0},170);let target=null,dist=2.7;for(const e of enemies){if(!e.alive)continue;const dx=e.x-player.position.x,dz=e.z-player.position.z,dd=Math.hypot(dx,dz);const ahead=(dx*Math.sin(facing)+(-dz)*Math.cos(facing))/Math.max(dd,.01);if(dd<dist&&ahead>-.3){target=e;dist=dd}}if(target){target.hp--;target.g.position.x+=Math.sin(facing)*.7;target.g.position.z-=Math.cos(facing)*.7;if(target.hp<=0){target.alive=false;target.g.visible=false;kills++;if(rand()<.68||target.boss)resource('shard',target.x,target.z);showToast(target.boss?'THE WARDEN FALLS':'SHADE BANISHED')}else showToast('A CLEAN STRIKE')}updateUI()}
function dodge(){if(!gameOn||stamina<22||dodgeTime>0)return;stamina-=22;dodgeTime=.36;invuln=.6}
function applyDamage(n){if(invuln>0)return;health=Math.max(0,health-n);invuln=.65;showToast('STRUCK · KEEP YOUR DISTANCE');if(health<=0){gameOn=false;$('#end-title').textContent='LOST TO THE WILDS';$('#end-copy').textContent='The old world is unforgiving. The flame can still be found.';$('#end-screen').classList.add('visible')}updateUI()}
function actionUse(){if(promptTarget)interact()}
window.addEventListener('keydown',e=>{keys[e.code]=true;if(['Space','ArrowUp','ArrowDown','ArrowLeft','ArrowRight'].includes(e.code))e.preventDefault();if(e.code==='KeyE'||e.code==='KeyF')actionUse();if(e.code==='Space')dodge();if(e.code==='Escape')$('#help-modal').classList.toggle('open')});window.addEventListener('keyup',e=>keys[e.code]=false);canvas.addEventListener('pointerdown',e=>{if(gameOn&&e.button===0)attack()});$('#mobile-hit').addEventListener('pointerdown',e=>{e.preventDefault();attack()});$('#mobile-dodge').addEventListener('pointerdown',e=>{e.preventDefault();dodge()});$('#mobile-use').addEventListener('pointerdown',e=>{e.preventDefault();actionUse()});
let stickX=0,stickY=0,stickActive=false;const stickZone=$('#stick-zone'),stick=$('#stick');stickZone.addEventListener('pointerdown',e=>{stickActive=true;stickZone.setPointerCapture(e.pointerId);moveStick(e)});stickZone.addEventListener('pointermove',e=>{if(stickActive)moveStick(e)});stickZone.addEventListener('pointerup',()=>{stickActive=false;stickX=stickY=0;stick.style.transform='translate(0,0)'});function moveStick(e){const r=stickZone.getBoundingClientRect(),dx=e.clientX-(r.left+r.width/2),dy=e.clientY-(r.top+r.height/2),l=Math.hypot(dx,dy),k=Math.min(l,34)/Math.max(l,1);stickX=dx*k/34;stickY=dy*k/34;stick.style.transform=`translate(${stickX*34}px,${stickY*34}px)`}
$('#start-btn').onclick=()=>{gameOn=true;$('#start-screen').classList.remove('visible');if(innerWidth<760)$('.mobile-controls').classList.add('active');showToast('YOUR ODYSSEY BEGINS');};$('#help-btn').onclick=()=>$('#help-modal').classList.add('open');$('#close-help').onclick=$('#resume-btn').onclick=()=>$('#help-modal').classList.remove('open');$('#again-btn').onclick=()=>location.reload();$('#sound-btn').onclick=()=>showToast('THE WILDS ARE QUIET');
updateUI();setBiome();

